"""
Template export dati e changelog versioni.
"""

TEMPLATE_EXPORT = '\n<!DOCTYPE html>\n<html>\n<head>\n<meta charset="utf-8">\n<title>TaskPlanner — Export</title>\n<style>\n:root {\n    --bg-color: #f0f4f8; --card-bg: #ffffff; --text-color: #222;\n    --muted-text: #555; --border-color: #ccc; --accent: #007bff;\n    --accent-hover: #0056b3; --danger: #dc3545; --success: #28a745;\n    --warning: #ff9800; --shadow: rgba(0,0,0,0.15);\n}\nbody.dark {\n    --bg-color: #151821; --card-bg: #1f2430; --text-color: #f5f5f5;\n    --muted-text: #aaaaaa; --border-color: #3a3f4b; --accent: #4da3ff;\n    --accent-hover: #1e7fd8; --danger: #ff6b6b; --success: #4cd964;\n    --warning: #ffc94a; --shadow: rgba(0,0,0,0.6);\n}\nbody { font-family: Arial, sans-serif; background: var(--bg-color); color: var(--text-color); margin: 0; padding: 30px; }\n.card { background: var(--card-bg); border-radius: 10px; padding: 28px 32px; max-width: 760px; margin: 0 auto; box-shadow: 0 2px 12px var(--shadow); }\nh1 { margin-top: 0; font-size: 1.5rem; }\n.section { margin-bottom: 22px; }\n.section h3 { margin: 0 0 10px 0; font-size: 1rem; border-bottom: 1px solid var(--border-color); padding-bottom: 5px; }\n.row2 { display: flex; gap: 16px; flex-wrap: wrap; }\n.row2 > div { flex: 1; min-width: 180px; }\ninput[type=date], select { padding: 6px 10px; border-radius: 6px; border: 1px solid var(--border-color); background: var(--bg-color); color: var(--text-color); font-size: 0.9rem; }\n.btn { padding: 9px 22px; border-radius: 7px; border: none; cursor: pointer; font-size: 0.95rem; font-weight: bold; }\n.btn-primary { background: var(--accent); color: #fff; }\n.btn-primary:hover { background: var(--accent-hover); }\n.btn-back { padding: 7px 16px; border-radius: 7px; border: 1px solid var(--border-color); background: transparent; color: var(--text-color); cursor: pointer; font-size: 0.88rem; text-decoration: none; display: inline-flex; align-items: center; gap: 5px; transition: background .15s; }\n.btn-back:hover { background: var(--border-color); }\n.page-header { display: flex; align-items: center; gap: 14px; margin-bottom: 24px; }\n.page-header h1 { margin: 0; font-size: 1.5rem; font-weight: 700; }\n.fmt-grid { display: flex; gap: 10px; flex-wrap: wrap; }\n.fmt-btn { padding: 8px 18px; border-radius: 8px; border: 2px solid var(--border-color); background: var(--bg-color); color: var(--text-color); cursor: pointer; font-size: 0.9rem; transition: all .15s; }\n.fmt-btn:hover { border-color: var(--accent); }\n.fmt-btn.selected { border-color: var(--accent); background: var(--accent); color: #fff; }\n.fields-grid { display: flex; flex-wrap: wrap; gap: 6px 18px; }\n.cb-pill { display: flex; align-items: center; gap: 5px; padding: 4px 10px; border-radius: 20px; border: 1px solid var(--border-color); background: var(--bg-color); cursor: pointer; font-size: 0.83rem; }\n.cb-pill input { accent-color: var(--accent); }\n.cb-pill.active { border-color: var(--accent); background: #007bff18; }\n.note { font-size: 0.8rem; color: var(--muted-text); margin-top: 6px; }\n.select-all-link { font-size: 0.78rem; color: var(--accent); cursor: pointer; margin-bottom: 8px; display: inline-block; text-decoration: underline; }\nlabel { display: flex; align-items: center; gap: 6px; font-size: 0.88rem; cursor: pointer; margin-bottom: 5px; }\nlabel input[type=checkbox] { accent-color: var(--accent); }\n</style>\n</head>\n<body>\n<div class="card">\n    <div class="page-header">\n        <a class="btn-back" href="/">← {{ _("Torna alla Home") }}</a>\n        <h1>📤 {{ _("Esporta Task") }}</h1>\n    </div>\n    <form method="POST" action="/export" id="exportForm">\n        <input type="hidden" name="format" id="hiddenFormat" value="csv">\n\n        <div class="section">\n            <h3>📅 {{ _("Periodo") }}</h3>\n            <div class="row2">\n                <div><small>{{ _("Dal") }}</small><br>\n                    <input type="date" name="date_from" id="date_from" value="{{ today[:7] }}-01">\n                </div>\n                <div><small>{{ _("Al") }}</small><br>\n                    <input type="date" name="date_to" id="date_to" value="{{ today }}">\n                </div>\n            </div>\n        </div>\n\n        <div class="section">\n            <h3>🚦 {{ _("Priorità") }}</h3>\n            <span class="select-all-link" onclick="toggleAll(\'prio\')">{{ _("Seleziona/Deseleziona tutto") }}</span>\n            <div class="fields-grid">\n                <label class="cb-pill"><input type="checkbox" class="prio-cb" name="priorita" value="Urgente" checked> 🚨 {{ _("Urgente") }}</label>\n                <label class="cb-pill"><input type="checkbox" class="prio-cb" name="priorita" value="Alta" checked> 🚩 {{ _("Alta") }}</label>\n                <label class="cb-pill"><input type="checkbox" class="prio-cb" name="priorita" value="Media" checked> 🍻 {{ _("Media") }}</label>\n                <label class="cb-pill"><input type="checkbox" class="prio-cb" name="priorita" value="Bassa" checked> 🏖️ {{ _("Bassa") }}</label>\n            </div>\n        </div>\n\n        <div class="section">\n            <h3>🏷️ {{ _("Categorie") }}</h3>\n            <span class="select-all-link" onclick="toggleAll(\'cat\')">{{ _("Seleziona/Deseleziona tutto") }}</span>\n            <div class="fields-grid">\n                {% for c in categories %}\n                <label class="cb-pill">\n                    <input type="checkbox" class="cat-cb" name="category_id" value="{{ c[0] }}" checked>\n                    <span style="width:9px;height:9px;border-radius:50%;background:{{ c[2] }};display:inline-block;flex-shrink:0;"></span>\n                    {{ c[1] }}\n                </label>\n                {% endfor %}\n            </div>\n        </div>\n\n        <div class="section">\n            <h3>📋 {{ _("Stato task") }}</h3>\n            <div class="fields-grid">\n                <label class="cb-pill"><input type="checkbox" name="stato" value="tutti" id="stato-tutti" checked onchange="toggleStato(this)"> 📦 {{ _("Tutti") }}</label>\n                <label class="cb-pill"><input type="checkbox" class="stato-cb" name="stato" value="aperto" checked> ⭕ {{ _("Aperti") }}</label>\n                <label class="cb-pill"><input type="checkbox" class="stato-cb" name="stato" value="completato" checked> ✅ {{ _("Completati") }}</label>\n            </div>\n            <div style="margin-top:10px;">\n                <label><input type="checkbox" name="solo_allegati" value="1"> 📎 {{ _("Solo task con allegati") }}</label>\n            </div>\n        </div>\n\n        <div class="section">\n            <h3>🔁 {{ _("Task ricorrenti") }}</h3>\n            <label><input type="checkbox" name="espandi_ricorrenti" value="1" id="espandi_ric"> {{ _("Espandi i task ricorrenti su tutte le giornate del periodo") }}</label>\n            <p class="note">{{ _("Se attivo, ogni task ricorrente genera una riga per ogni occorrenza nel periodo selezionato.") }}</p>\n            <label><input type="checkbox" name="escludi_ricorrenti" value="1" id="escludi_ric"> {{ _("Escludi completamente i task ricorrenti dall&#39;export") }}</label>\n        </div>\n\n        <div class="section">\n            <h3>🎛️ {{ _("Campi da includere") }}</h3>\n            <span class="select-all-link" onclick="toggleAll(\'fields\')">{{ _("Seleziona/Deseleziona tutto") }}</span>\n            <div class="fields-grid">\n                <label class="cb-pill"><input type="checkbox" class="fields-cb" name="fields" value="occurrence_date" checked> 📅 {{ _("Data") }}</label>\n                <label class="cb-pill"><input type="checkbox" class="fields-cb" name="fields" value="titolo" checked> 📝 {{ _("Titolo") }}</label>\n                <label class="cb-pill"><input type="checkbox" class="fields-cb" name="fields" value="stato" checked> 📋 {{ _("Stato") }}</label>\n                <label class="cb-pill"><input type="checkbox" class="fields-cb" name="fields" value="priorita" checked> 🚦 {{ _("Priorità") }}</label>\n                <label class="cb-pill"><input type="checkbox" class="fields-cb" name="fields" value="categoria" checked> 🏷️ {{ _("Categoria") }}</label>\n                <label class="cb-pill"><input type="checkbox" class="fields-cb" name="fields" value="ora_prevista"> ⏰ {{ _("Orario") }}</label>\n                <label class="cb-pill"><input type="checkbox" class="fields-cb" name="fields" value="ricorrenza"> 🔁 {{ _("Ricorrenza") }}</label>\n                <label class="cb-pill"><input type="checkbox" class="fields-cb" name="fields" value="url"> 🔗 {{ _("URL") }}</label>\n                <label class="cb-pill"><input type="checkbox" class="fields-cb" name="fields" value="created_at"> 🗓️ {{ _("Creato il") }}</label>\n                <label class="cb-pill"><input type="checkbox" class="fields-cb" name="fields" value="id"> 🔢 ID</label>\n                <label class="cb-pill"><input type="checkbox" class="fields-cb" name="fields" value="data_prevista"> 📌 Data prevista orig.</label>\n                <label class="cb-pill"><input type="checkbox" class="fields-cb" name="fields" value="allegati"> 📎 Allegati</label>\n            </div>\n        </div>\n\n        <div class="section">\n            <h3>💾 {{ _("Formato di esportazione") }}</h3>\n            <div class="fmt-grid" id="fmtGrid">\n                <button type="button" class="fmt-btn selected" data-fmt="csv" onclick="selectFmt(this)">📊 {{ _("CSV") }}</button>\n                <button type="button" class="fmt-btn" data-fmt="txt" onclick="selectFmt(this)">📄 {{ _("TXT") }}</button>\n                <button type="button" class="fmt-btn" data-fmt="json" onclick="selectFmt(this)">🗄️ {{ _("JSON") }}</button>\n                <button type="button" class="fmt-btn" data-fmt="md" onclick="selectFmt(this)">📋 {{ _("Markdown") }}</button>\n            </div>\n            <p class="note">\n                <strong>CSV</strong>: per Excel / LibreOffice Calc &nbsp;|&nbsp;\n                <strong>TXT</strong>: leggibile in qualsiasi editor &nbsp;|&nbsp;\n                <strong>JSON</strong>: integrazione con altri sistemi &nbsp;|&nbsp;\n                <strong>Markdown</strong>: documentazione / Obsidian / Notion\n            </p>\n        </div>\n\n        <div style="margin-top:18px;">\n            <button type="submit" class="btn btn-primary">⬇️ {{ _("Esporta") }}</button>\n        </div>\n    </form>\n</div>\n<script>\nfunction selectFmt(btn) {\n    document.querySelectorAll(\'.fmt-btn\').forEach(b => b.classList.remove(\'selected\'));\n    btn.classList.add(\'selected\');\n    document.getElementById(\'hiddenFormat\').value = btn.dataset.fmt;\n}\nfunction toggleAll(group) {\n    const map = { prio: \'.prio-cb\', cat: \'.cat-cb\', fields: \'.fields-cb\' };\n    const cbs = document.querySelectorAll(map[group]);\n    const anyUnchecked = Array.from(cbs).some(cb => !cb.checked);\n    cbs.forEach(cb => cb.checked = anyUnchecked);\n}\nfunction toggleStato(cb) {\n    if (cb.checked) document.querySelectorAll(\'.stato-cb\').forEach(s => s.checked = true);\n}\ndocument.querySelectorAll(\'.stato-cb\').forEach(cb => {\n    cb.addEventListener(\'change\', () => { document.getElementById(\'stato-tutti\').checked = false; });\n});\ndocument.getElementById(\'escludi_ric\').addEventListener(\'change\', function() {\n    if (this.checked) document.getElementById(\'espandi_ric\').checked = false;\n});\ndocument.getElementById(\'espandi_ric\').addEventListener(\'change\', function() {\n    if (this.checked) document.getElementById(\'escludi_ric\').checked = false;\n});\nconst savedTheme = localStorage.getItem(\'taskplanner_theme\');\nif (savedTheme === \'dark\') document.body.classList.add(\'dark\');\n</script>\n</body>\n</html>\n'

TEMPLATE_CHANGELOG = '\n<!DOCTYPE html>\n<html>\n<head>\n<meta charset="utf-8">\n<title>TaskPlanner — Changelog</title>\n<style>\n:root {\n    --bg-color: #f0f4f8; --card-bg: #ffffff; --text-color: #222;\n    --muted-text: #555; --border-color: #ccc; --accent: #007bff;\n    --shadow: rgba(0,0,0,0.15);\n}\nbody.dark {\n    --bg-color: #151821; --card-bg: #1f2430; --text-color: #f5f5f5;\n    --muted-text: #aaaaaa; --border-color: #3a3f4b; --accent: #4da3ff;\n    --shadow: rgba(0,0,0,0.6);\n}\nbody { font-family: Arial, sans-serif; background: var(--bg-color); color: var(--text-color); margin: 0; padding: 30px; }\n.card { background: var(--card-bg); border-radius: 10px; padding: 28px 32px; max-width: 680px; margin: 0 auto; box-shadow: 0 2px 12px var(--shadow); }\n.page-header { display: flex; align-items: center; gap: 14px; margin-bottom: 24px; }\n.page-header h1 { margin: 0; font-size: 1.5rem; }\n.ver-block { margin-bottom: 28px; border-left: 4px solid var(--accent); padding-left: 14px; }\n.ver-block.latest { border-color: #28a745; }\n.ver-header { display: flex; align-items: baseline; gap: 10px; margin-bottom: 8px; flex-wrap: wrap; }\n.ver-num { font-size: 1.1rem; font-weight: bold; }\n.ver-name { font-size: 0.85rem; color: var(--muted-text); font-style: italic; }\n.ver-date { font-size: 0.78rem; color: var(--muted-text); margin-left: auto; }\n.ver-badge { font-size: 0.7rem; background: #28a745; color: #fff; padding: 2px 7px; border-radius: 10px; font-weight: bold; }\nul { margin: 0; padding-left: 18px; }\nli { font-size: 0.88rem; margin-bottom: 4px; line-height: 1.5; }\n.btn-back { padding: 7px 16px; border-radius: 7px; border: 1px solid var(--border-color); background: transparent; color: var(--text-color); cursor: pointer; font-size: 0.88rem; text-decoration: none; display: inline-flex; align-items: center; gap: 5px; transition: background .15s; }\n.btn-back:hover { background: var(--border-color); }\n</style>\n</head>\n<body>\n<div class="card">\n    <div class="page-header">\n        <a class="btn-back" href="/">← {{ _("Torna alla Home") }}</a>\n        <h1>📋 {{ _("Changelog") }} — TaskPlanner</h1>\n    </div>\n    {% for entry in changelog %}\n    <div class="ver-block {% if loop.first %}latest{% endif %}">\n        <div class="ver-header">\n            <span class="ver-num">v{{ entry.version }}</span>\n            <span class="ver-name">{{ entry.codename }}</span>\n            {% if loop.first %}<span class="ver-badge">CURRENT</span>{% endif %}\n            <span class="ver-date">{{ entry.date }}</span>\n        </div>\n        <ul>\n            {% for note in entry.notes %}\n            <li>{{ note }}</li>\n            {% endfor %}\n        </ul>\n    </div>\n    {% endfor %}\n    {% if support_url %}\n    <p style="text-align:center; margin-top:24px; font-size:0.9rem;">\n        {{ _("Ti piace TaskPlanner? Sostieni lo sviluppo") }}: <a href="{{ support_url }}" target="_blank" rel="noopener" style="color:var(--accent);">☕ {{ _("Offrimi un caffè") }}</a>\n    </p>\n    {% endif %}\n</div>\n<script>\nconst savedTheme = localStorage.getItem(\'taskplanner_theme\');\nif (savedTheme === \'dark\') document.body.classList.add(\'dark\');\n</script>\n</body>\n</html>\n'
